import { Component, Input, Output, EventEmitter, OnChanges, SimpleChanges, ElementRef } from '@angular/core';
import { ScaleResult } from 'app/shared/models/scale-result';

interface Band { x:number; y:number; width:number; height:number; }
interface RangeLabel { x:number; y:number; text:string; }
interface Bar { x:number; y:number; width:number; height:number; }
// Matches the bubble used by SvgSummaryScalesChartComponent so the two chart
// types read consistently across a report.
interface ScoreBubble { rectX:number; rectY:number; width:number; height:number; rx:number; textX:number; textY:number; text:string; pointer:string|null; }

/**
 * Pure-SVG re-implementation of ScaleChartComponent (Option B).
 *
 * A single score bar drawn against the scale's score axis, with the scale
 * ranges shown as faint alternating bands and their names labeled at each
 * range midpoint. Inline SVG prints natively/crisply, so there is no
 * canvas-to-image rasterization and none of its timing/blank-image issues.
 * Mirrors the original @Input/@Output API for drop-in template replacement.
 */
@Component({
  selector: 'app-svg-scale-chart',
  templateUrl: './svg-scale-chart.component.html',
  styleUrls: ['./svg-scale-chart.component.css']
})
export class SvgScaleChartComponent implements OnChanges {

  private static readonly W = 700;
  private static readonly H = 420;
  private static readonly MARGIN_LEFT = 160;
  private static readonly MARGIN_RIGHT = 12;
  private static readonly MARGIN_TOP = 24;
  private static readonly MARGIN_BOTTOM_WITH_NAME = 40;
  private static readonly MARGIN_BOTTOM = 14;
  private static readonly MAX_BAR_WIDTH = 60;
  // Score bubble geometry (shared look with the summary scales chart).
  private static readonly BUBBLE_HEIGHT = 20;
  private static readonly BUBBLE_POINTER_H = 5;
  private static readonly BUBBLE_MIN_WIDTH = 22;
  private static readonly BUBBLE_CHAR_WIDTH = 8;
  private static readonly BUBBLE_PAD_X = 14;

  @Input("scale-result") scaleResult:ScaleResult;
  @Input("show-scale-name") showScaleName:Boolean;
  @Input("show-ranges") showRanges:Boolean = true;
  @Output() complete = new EventEmitter<any>();

  public readonly viewBox = `0 0 ${SvgScaleChartComponent.W} ${SvgScaleChartComponent.H}`;
  public bands:Band[] = [];
  public rangeLabels:RangeLabel[] = [];
  public bar:Bar = null;
  public scoreBubble:ScoreBubble = null;
  public scaleNameLabel:string = "";

  constructor(private element:ElementRef) {}

  ngOnChanges(changes:SimpleChanges) {
    this.recompute();
    // Preserve the original component's "complete" signal for any listeners.
    this.complete.emit(null);
  }

  public get hasResult() {
    return this.scaleResult != null && this.scaleResult.scale != null
      && this.scaleResult.scale.getMaxRange() != null;
  }

  private recompute() {
    this.bands = [];
    this.rangeLabels = [];
    this.bar = null;
    this.scoreBubble = null;
    this.scaleNameLabel = "";
    if (!this.hasResult) {
      return;
    }

    const C = SvgScaleChartComponent;
    const scale = this.scaleResult.scale;
    const maxScore = scale.getMaxRange().rangeEnd || 1;

    const marginBottom = this.showScaleName === true ? C.MARGIN_BOTTOM_WITH_NAME : C.MARGIN_BOTTOM;
    const x0 = C.MARGIN_LEFT;
    const y0 = C.MARGIN_TOP;
    const plotW = C.W - C.MARGIN_LEFT - C.MARGIN_RIGHT;
    const plotH = C.H - C.MARGIN_TOP - marginBottom;

    // Map a score value to a y pixel (0 at the bottom of the plot).
    const yFor = (score:number) => y0 + plotH - (Math.max(0, Math.min(score, maxScore)) / maxScore) * plotH;

    if (this.showRanges !== false) {
      scale.ranges.forEach((r, i) => {
        const topY = yFor(r.rangeEnd);
        const bottomY = yFor(r.rangeStart);
        // Faint alternating band, matching the original's even-range shading.
        if (i % 2 === 1) {
          this.bands.push({ x: x0, y: topY, width: plotW, height: Math.max(0, bottomY - topY) });
        }
        // Range name label at the range midpoint.
        this.rangeLabels.push({ x: x0 - 6, y: yFor(r.midPoint) + 4, text: r.displayName || "" });
      });
    }

    // Single score bar.
    const score = this.scaleResult.score || 0;
    const barW = Math.min(C.MAX_BAR_WIDTH, plotW * 0.25);
    const centerX = x0 + plotW / 2;
    const barTop = yFor(score);
    this.bar = { x: centerX - barW / 2, y: barTop, width: barW, height: (y0 + plotH) - barTop };
    // Score bubble above the bar (matching the summary scales chart).
    this.scoreBubble = this.buildScoreBubble(centerX, barTop, y0);

    if (this.showScaleName === true) {
      this.scaleNameLabel = scale.name || "";
    }
  }

  /**
   * Builds the rounded score bubble shown over the bar. It floats above the bar
   * with a small downward pointer, or drops just inside the bar top when the bar
   * reaches the plot ceiling. Width grows with the score text (1-3 digits and
   * decimals fit) and is clamped horizontally so it never overflows the viewBox.
   * Mirrors SvgSummaryScalesChartComponent.buildScoreBubble for a consistent look.
   */
  private buildScoreBubble(centerX:number, barTop:number, y0:number) : ScoreBubble {
    const C = SvgScaleChartComponent;
    const text = this.safeScoreText();
    const width = Math.max(C.BUBBLE_MIN_WIDTH, text.length * C.BUBBLE_CHAR_WIDTH + C.BUBBLE_PAD_X);
    const height = C.BUBBLE_HEIGHT;

    const desiredTop = barTop - C.BUBBLE_POINTER_H - height;
    const above = desiredTop >= y0;
    const rectY = above ? desiredTop : barTop + 3;

    const minX = 2;
    const maxX = C.W - width - 2;
    const rectX = Math.max(minX, Math.min(maxX, centerX - width / 2));

    const pointer = above
      ? `${centerX - 5},${rectY + height} ${centerX + 5},${rectY + height} ${centerX},${rectY + height + C.BUBBLE_POINTER_H}`
      : null;

    return {
      rectX, rectY, width, height, rx: 5,
      textX: rectX + width / 2,
      textY: rectY + height * 0.68,
      text,
      pointer
    };
  }

  private safeScoreText() : string {
    try {
      return this.scaleResult.getScoreForDisplay();
    }
    catch (e) {
      return String(this.scaleResult.score != null ? this.scaleResult.score : "");
    }
  }
}
