import { Component, Input, OnChanges, SimpleChanges, ElementRef } from '@angular/core';
import { ScaleResult } from 'app/shared/models/scale-result';
import { ScaleResultColorService } from 'app/assessment-charts/services/scale-result-color.service';

interface Band { x:number; y:number; width:number; height:number; color:string; }
interface YLabel { x:number; y:number; text:string; }
interface Bar { x:number; y:number; width:number; height:number; }
interface XLabel { x:number; y:number; text:string; }
// A rounded "bubble" that floats the score above (or, when the bar is too tall,
// just inside the top of) each bar -- the always-on replacement for the old
// Chart.js hover tooltip.
interface ScoreBubble { rectX:number; rectY:number; width:number; height:number; rx:number; textX:number; textY:number; text:string; pointer:string|null; }

/**
 * Pure-SVG re-implementation of SummaryScalesChartComponent (Option B).
 *
 * Renders the same visual as the Chart.js version -- horizontal colored
 * severity bands with one blue bar per scale result rising from the bottom --
 * but as inline SVG. SVG prints natively and crisply at any scale, so there is
 * no <canvas>-to-image rasterization step and none of its timing/blank-image
 * failure modes. The component exposes the same @Input API as the original so
 * it is a drop-in replacement at the template level.
 */
@Component({
  selector: 'app-svg-summary-scales-chart',
  templateUrl: './svg-summary-scales-chart.component.html',
  styleUrls: ['./svg-summary-scales-chart.component.css']
})
export class SvgSummaryScalesChartComponent implements OnChanges {

  private static readonly MAX_SCALE_NAME_LENGTH = 75;

  // Fixed SVG user-space canvas; the viewBox makes it scale to any container.
  private static readonly W = 700;
  private static readonly H = 420;
  private static readonly MARGIN_LEFT = 150;
  private static readonly MARGIN_RIGHT = 12;
  private static readonly MARGIN_TOP = 12;
  private static readonly MARGIN_BOTTOM_WITH_NAMES = 46;
  private static readonly MARGIN_BOTTOM = 12;
  private static readonly MAX_BAR_WIDTH = 50;
  // Score bubble geometry (SVG user-space units).
  private static readonly BUBBLE_HEIGHT = 20;
  private static readonly BUBBLE_POINTER_H = 5;
  private static readonly BUBBLE_MIN_WIDTH = 22;
  private static readonly BUBBLE_CHAR_WIDTH = 8;
  private static readonly BUBBLE_PAD_X = 14;

  @Input("scaleResults") scaleResults:ScaleResult[];
  @Input("showNames") showNames:Boolean;
  @Input("showRangeScore") showRangeScore:Boolean;
  @Input("chartScaleNames") chartScaleNames:string[];
  @Input("chartRangeNames") chartRangeNames:string[];
  @Input("reverseDirection") reverseDirection:boolean = false;

  public readonly viewBox = `0 0 ${SvgSummaryScalesChartComponent.W} ${SvgSummaryScalesChartComponent.H}`;
  public bands:Band[] = [];
  public yLabels:YLabel[] = [];
  public bars:Bar[] = [];
  public xLabels:XLabel[] = [];
  public bubbles:ScoreBubble[] = [];

  constructor(private element:ElementRef, private colorService:ScaleResultColorService) {}

  ngOnChanges(changes:SimpleChanges) {
    this.recompute();
  }

  public get hasResults() {
    return this.scaleResults != null && this.scaleResults.length > 0
      && this.scaleResults[0].scale && this.scaleResults[0].scale.ranges
      && this.scaleResults[0].scale.ranges.length > 0;
  }

  private recompute() {
    this.bands = [];
    this.yLabels = [];
    this.bars = [];
    this.xLabels = [];
    this.bubbles = [];
    if (!this.hasResults) {
      return;
    }

    const C = SvgSummaryScalesChartComponent;
    const ranges = this.scaleResults[0].scale.ranges;
    const n = ranges.length;

    const marginBottom = this.showNames === true ? C.MARGIN_BOTTOM_WITH_NAMES : C.MARGIN_BOTTOM;
    const x0 = C.MARGIN_LEFT;
    const y0 = C.MARGIN_TOP;
    const plotW = C.W - C.MARGIN_LEFT - C.MARGIN_RIGHT;
    const plotH = C.H - C.MARGIN_TOP - marginBottom;
    const bandH = plotH / n;

    // Colored severity bands (band 0 at the bottom). Colors only are reversed
    // for reverseDirection, matching the original behavior.
    let colors = this.colorService.getBackgroundColors(n).map(c => c.color);
    if (this.reverseDirection) {
      colors = colors.slice().reverse();
    }
    const rangeNames = this.getChartRangeNames();
    for (let i = 0; i < n; i++) {
      const topY = y0 + (n - 1 - i) * bandH;
      if (colors[i]) {
        this.bands.push({ x: x0, y: topY, width: plotW, height: bandH, color: colors[i] });
      }
      // y-axis label sits just inside the top edge of its band.
      this.yLabels.push({ x: x0 - 6, y: topY + 14, text: rangeNames[i] || "" });
    }

    // One blue bar per scale result, height = (rangeIndex + scorePercent) / n.
    const m = this.scaleResults.length;
    const slot = plotW / m;
    const barW = Math.min(C.MAX_BAR_WIDTH, slot * 0.5);
    const names = this.getLabelsForScales();
    this.scaleResults.forEach((sr, j) => {
      const rangeIndex = sr.scale.ranges.indexOf(sr.range);
      let scorePercent = this.safeRangePercent(sr) / 100;
      if (scorePercent <= 0) {
        scorePercent += 0.10;
      }
      const value = Math.max(0, rangeIndex) + scorePercent;
      const frac = Math.min(1, value / n);
      const barH = frac * plotH;
      const centerX = x0 + slot * j + slot / 2;
      const barTop = y0 + plotH - barH;
      this.bars.push({ x: centerX - barW / 2, y: barTop, width: barW, height: barH });

      this.bubbles.push(this.buildScoreBubble(sr, centerX, barTop, y0));

      if (this.showNames === true) {
        this.xLabels.push({ x: centerX, y: y0 + plotH + 18, text: names[j] || "" });
      }
    });
  }

  /**
   * Builds an always-on score "bubble" for a bar. The bubble normally floats
   * just above the bar with a small pointer; if the bar reaches the top of the
   * plot there is no room above, so the bubble drops just inside the bar top and
   * the pointer is omitted. Bubble width grows with the score text so 1-3 digit
   * (and decimal) scores all fit, and it is clamped horizontally so edge bars
   * never overflow the SVG viewBox.
   */
  private buildScoreBubble(sr:ScaleResult, centerX:number, barTop:number, y0:number) : ScoreBubble {
    const C = SvgSummaryScalesChartComponent;
    const text = this.safeScoreText(sr);
    const width = Math.max(C.BUBBLE_MIN_WIDTH, text.length * C.BUBBLE_CHAR_WIDTH + C.BUBBLE_PAD_X);
    const height = C.BUBBLE_HEIGHT;

    const desiredTop = barTop - C.BUBBLE_POINTER_H - height;
    const above = desiredTop >= y0;
    const rectY = above ? desiredTop : barTop + 3;

    // Keep the bubble inside the drawing area horizontally.
    const minX = 2;
    const maxX = C.W - width - 2;
    const rectX = Math.max(minX, Math.min(maxX, centerX - width / 2));

    const pointer = above
      ? `${centerX - 5},${rectY + height} ${centerX + 5},${rectY + height} ${centerX},${rectY + height + C.BUBBLE_POINTER_H}`
      : null;

    return {
      rectX, rectY, width, height, rx: 5,
      textX: rectX + width / 2,
      textY: rectY + height * 0.68,
      text,
      pointer
    };
  }

  private safeScoreText(sr:ScaleResult) : string {
    try {
      return sr.getScoreForDisplay();
    }
    catch (e) {
      return String(sr.score != null ? sr.score : "");
    }
  }

  private safeRangePercent(sr:ScaleResult) : number {
    try {
      return sr.range.getPercentageForRange(sr.score);
    }
    catch (e) {
      // Score out of its range bounds; clamp instead of throwing.
      return sr.score <= sr.range.rangeStart ? 0 : 100;
    }
  }

  private getLabelsForScales() : string[] {
    let labels = this.scaleResults.map(sr =>
      sr.scale.name.substring(0, Math.min(sr.scale.name.length, SvgSummaryScalesChartComponent.MAX_SCALE_NAME_LENGTH)));
    if (this.chartScaleNames) {
      if (this.chartScaleNames.length == this.scaleResults.length) {
        labels = this.chartScaleNames;
      }
      else {
        console.error("chart scale names", this.chartScaleNames, " do not match number of scales ", this.scaleResults);
      }
    }
    return labels;
  }

  private getChartRangeNames() : string[] {
    const ranges = this.scaleResults[0].scale.ranges;
    let names = this.chartRangeNames;
    if (!names || names.length == 0) {
      return ranges.map(r => {
        let name = r.displayName || "";
        if (this.showRangeScore !== false) {
          name += " (" + r.rangeEnd + ")";
        }
        return name;
      });
    }
    if (names.length != ranges.length) {
      console.error("Scale range names does not match count of scale ranges");
      return names;
    }
    return names.map((v, i) => v + " (" + ranges[i].rangeEnd + ")");
  }

  /**
   * Parity with the Chart.js component: hands back a printable image of the
   * chart. Serializes the rendered SVG into a data-URL <img> so existing print
   * paths (e.g. therapist-scale-results.getPrintContent()) keep working.
   */
  public getChartAsHtmlImageElement() : HTMLImageElement {
    const img = new Image();
    const svg = (this.element.nativeElement as HTMLElement).querySelector('svg');
    if (svg) {
      try {
        const serialized = new XMLSerializer().serializeToString(svg);
        img.src = 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(serialized)));
      }
      catch (e) {
        console.error("Failed to serialize SVG chart to image", e);
      }
    }
    return img;
  }
}
